export class Classic{getBegin(){return`<div class="row form-group align-items-center dyjsform_entity">`}getEnd(){return`<div>`}getForm(selector){const outputName=selector.replace("#","");return`\n            <div class="dyjsform_container"></div>\n            <div  class="dyjsform_footer" class=" row form-group align-items-center">\n                <div class="col-md-3"></div>\n                <div class="col-md-12">\n                    <button type="button" class="form-control btn btn-primary dyjsform_action_add">\n                        <i class="fas fa-plus"></i> Ajouter\n                    </button>\n                </div>\n            </div>\n\x3c!--                <textarea rows="30" cols="150" name="${outputName}[output]"--\x3e\n                <textarea hidden name="${outputName}[output]"\n                       class="output"></textarea>\n            `}getField(field,rowIndex,BSColumnWidth){const type=field.type?`type="${field.type}"`:"";const value=field.value?`value="${this._escapeHtml(field.value)}"`:"";let content="";const className=field.className?`${field.className}`:"";const attr=field.attr?`${field.attr}`:"";const name=!field.name.startsWith("dyjsform_action_")?`name="dyjsform[${field.name}_${rowIndex}]"`:"";if(field.htmlElement==="select"&&field.options){content+=`<option></option>`;field.options.forEach((option=>{let selected=field.value===option.value?"selected":"";content+=`<option ${selected} value="${option.value}">${option.name}</option>`}))}else if(field.htmlElement==="textarea"){content=field.value?`${this._escapeHtml(field.value)}`:""}else{content=field.content?`${field.content}`:""}return`<div class="form-group col-md-${BSColumnWidth}">\n            <div class="col-md-12">${field.label===""?"&nbsp;":field.label}</div>\n            <div class="col-md-12">\n                <${field.htmlElement} ${name} class="form-control dyjsform_input ${field.name} ${className}" ${attr} ${type} ${value} \n                data-row="${rowIndex}" data-name="${field.name}">${content}</${field.htmlElement}>\n                <span class="text-danger djf_error">${field.error}</span>\n            </div>\n        </div>`}getCss(){return``}_escapeHtml(str){return str.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;")}}